class Solution {
    int evaluate(const vector<int>& as, const vector<int>& ad,
                 const vector<int>& bs, const vector<int>& bd) {
        int m = bs.size();
        vector<pair<int,int>> rides(m);
        for (int i = 0; i < m; ++i) rides[i] = {bs[i], bd[i]};
        sort(rides.begin(), rides.end());
        vector<int> pref(m), suff(m + 1, INT_MAX);
        for (int i = 0; i < m; ++i)
            pref[i] = min(i ? pref[i - 1] : INT_MAX, rides[i].second);
        for (int i = m - 1; i >= 0; --i)
            suff[i] = min(suff[i + 1], rides[i].first + rides[i].second);
        int ans = INT_MAX;
        for (int i = 0; i < (int)as.size(); ++i) {
            int finish = as[i] + ad[i];
            int pos = upper_bound(rides.begin(), rides.end(), make_pair(finish, INT_MAX)) - rides.begin();
            if (pos > 0) ans = min(ans, finish + pref[pos - 1]);
            if (pos < m) ans = min(ans, suff[pos]);
        }
        return ans;
    }
public:
    int earliestFinishTime(vector<int>& landStartTime, vector<int>& landDuration,
                           vector<int>& waterStartTime, vector<int>& waterDuration) {
        return min(evaluate(landStartTime, landDuration, waterStartTime, waterDuration),
                   evaluate(waterStartTime, waterDuration, landStartTime, landDuration));
    }
};
